source='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            layers=[]
            while r0 <= r1 and c0 <= c1:
                border=[]
                border.extend(grid[r0][x] for x in range(c0,c1+1))
                if r1 != r0: border.extend(grid[r1][x] for x in range(c0,c1+1))
                if r1-r0 > 1:
                    border.extend(grid[y][c0] for y in range(r0+1,r1))
                    if c1 != c0: border.extend(grid[y][c1] for y in range(r0+1,r1))
                color=Counter(border).most_common(1)[0][0]
                if not layers or layers[-1] != color:
                    layers.append(color)
                r0+=1; r1-=1; c0+=1; c1-=1
            mapping={a:b for a,b in zip(layers,reversed(layers))}
            for y,x in cells:
                out[y][x]=mapping.get(grid[y][x],grid[y][x])
    return out
'''
